using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using Grasshopper.Kernel;using Grasshopper.Kernel.Parameters;using Grasshopper.Kernel.Special;using Grasshopper.Kernel.Types;using Rhino.Geometry;
namespace TopoptLab.GH {
 public static class FinalExample {
  static T Add<T>(List<IGH_DocumentObject>a,T o,float x,float y)where T:IGH_DocumentObject{o.CreateAttributes();o.Attributes.Pivot=new PointF(x,y);a.Add(o);return o;}
  static GH_NumberSlider Slider(List<IGH_DocumentObject>a,string name,decimal value,decimal min,decimal max,int decimals,float x,float y){var s=new GH_NumberSlider();s.NickName=name;s.Slider.Minimum=min;s.Slider.Maximum=max;s.Slider.DecimalPlaces=decimals;s.Slider.Type=decimals==0?Grasshopper.GUI.Base.GH_SliderAccuracy.Integer:Grasshopper.GUI.Base.GH_SliderAccuracy.Float;s.SetSliderValue(value);return Add(a,s,x,y);}
  static GH_Panel Note(List<IGH_DocumentObject>a,string text,float x,float y,float w,float h){var p=Add(a,new GH_Panel(),x,y);p.UserText=text;p.Attributes.Bounds=new RectangleF(x,y,w,h);return p;}
  public static List<IGH_DocumentObject> Build(){
   var a=EngineeringExample.Build(true,false,true);var solvers=a.OfType<EngineeringSolveComponent>().ToArray();var settings=a.OfType<EngineeringSettingsComponent>().Single();var review=a.OfType<ReviewControlsComponent>().Single();var limits=a.OfType<DesignLimitsComponent>().Single();
   var stage=(GH_NumberSlider)review.Params.Input[0].Sources[0];stage.Slider.Maximum=4;stage.NickName="VIEW: 0 baseline / 1 design / 2 voxel / 3 surface / 4 final FEM";
   var deformation=a.OfType<GH_NumberSlider>().Single(s=>s.NickName=="Deformation display factor");var maximum=a.OfType<GH_NumberSlider>().Single(s=>s.NickName=="Shared legend maximum / 0 auto");
   Note(a,"FINAL GEOMETRY AND PRINT REVIEW / STAGE 3\nAfter OPTIMIZATION completes, press EXTRACT. Keep regions are restored exactly; the original voxel envelope is retained.\nOrange = overhang beyond the selected angle; red = sampled normal thickness below the requested wall size.\nUse VIEW 3. Inspect Report and export STL. This stage has not been structurally reanalysed.\nOptional Edited mesh: a closed Rhino mesh inside the original envelope, with all Keep material preserved.",20,2740,1200,210);
   var print=Add(a,new PrintReviewComponent(),650,3070);var direction=Add(a,new Param_Vector{NickName="Print build direction / upward"},30,3000);direction.SetPersistentData(new GH_Vector(Vector3d.ZAxis));print.Params.Input[0].AddSource(direction);
   print.Params.Input[1].AddSource(Slider(a,"Print overhang angle from vertical / degrees",45,1,89,0,30,3080));print.Params.Input[2].AddSource(Slider(a,"Sampled minimum wall / mm",2,0,10,2,30,3140));
   Note(a,"",20,3260,1150,180).AddSource(print.Params.Output[1]);
   var surface=Add(a,new FinalGeometry3DComponent(),1500,3050);surface.Params.Input[0].AddSource(solvers[1].Params.Output[0]);surface.Params.Input[1].AddSource(settings.Params.Input[10].Sources[0]);surface.Params.Input[2].AddSource(Slider(a,"Surface smoothing / cells",.5m,0,2,2,1040,2830));surface.Params.Input[3].AddSource(print.Params.Output[0]);
   var edited=Add(a,new Param_Mesh{NickName="Optional edited closed mesh",Hidden=true},1040,2940);surface.Params.Input[4].AddSource(edited);
   for(int k=0;k<3;k++)surface.Params.Input[5+k].AddSource(Add(a,new GH_ButtonObject{NickName=new[]{"EXTRACT","STOP","RESET"}[k]},1290,3230+k*50));
   var surfaceView=Add(a,new FinalResults3DComponent(),1910,3050);surfaceView.Params.Input[0].AddSource(surface.Params.Output[0]);surfaceView.Params.Input[4].AddSource(review.Params.Output[5]);surfaceView.Params.Input[5].AddSource(Add(a,new GH_ButtonObject{NickName="BAKE SURFACE"},1720,3260));
   Note(a,"",2130,2950,900,240).AddSource(surfaceView.Params.Output[1]);Note(a,"",1720,3400,1220,90).AddSource(surface.Params.Output[1]);Note(a,"",1720,3510,1220,80).AddSource(surface.Params.Output[2]);Note(a,"",1720,3610,1220,80).AddSource(surface.Params.Output[3]);
   Note(a,"CONFORMING FINAL FEM / STAGE 4\nAfter EXTRACT completes, press FINAL FEM. A new TET4 mesh follows the extracted surface.\nSupports must cover complete original boundary faces. Loads must remain on the boundary; transfer checks force and moment.\nLevels 1: one analysis. Levels 3: sizes h, 0.75h and 0.5625h; compare every case. Three meshes do not automatically imply accuracy.\nUse VIEW 4 and select Case / Field above. Stress peaks near concentrated loads may remain mesh dependent.",20,3770,1200,230);
   var fem=Add(a,new FinalFem3DComponent(),1500,4150);fem.Params.Input[0].AddSource(surface.Params.Output[0]);fem.Params.Input[1].AddSource(Slider(a,"Final tetrahedral mesh size / mm",6,2,12,2,1040,3910));fem.Params.Input[2].AddSource(settings.Params.Output[0]);fem.Params.Input[3].AddSource(Slider(a,"Final mesh study levels",1,1,3,0,1040,3970));fem.Params.Input[4].AddSource(Slider(a,"Mesh study relative tolerance",.05m,.001m,.2m,3,1040,4030));fem.Params.Input[5].AddSource(limits.Params.Output[0]);
   for(int k=0;k<3;k++)fem.Params.Input[6+k].AddSource(Add(a,new GH_ButtonObject{NickName=new[]{"FINAL FEM","STOP","RESET"}[k]},1290,4350+k*50));
   var select=Add(a,new CaseResultComponent(),1720,4070);select.Params.Input[0].AddSource(fem.Params.Output[0]);select.Params.Input[1].AddSource(review.Params.Output[3]);var finalView=Add(a,new FinalResults3DComponent(),1910,4150);finalView.Params.Input[0].AddSource(select.Params.Output[0]);finalView.Params.Input[1].AddSource(review.Params.Output[4]);finalView.Params.Input[2].AddSource(deformation);finalView.Params.Input[3].AddSource(maximum);finalView.Params.Input[4].AddSource(review.Params.Output[6]);finalView.Params.Input[5].AddSource(Add(a,new GH_ButtonObject{NickName="BAKE FINAL MESH"},1720,4370));
   Note(a,"",2130,4050,900,320).AddSource(finalView.Params.Output[1]);Note(a,"",1720,4520,1220,90).AddSource(fem.Params.Output[1]);Note(a,"",1720,4630,1220,80).AddSource(fem.Params.Output[2]);
   var compare=Add(a,new CompareResultsComponent(),3100,4190);compare.Params.Input[0].AddSource(solvers[0].Params.Output[0]);compare.Params.Input[1].AddSource(fem.Params.Output[0]);Note(a,"",3300,4090,850,340).AddSource(compare.Params.Output[0]);
   return a;
  }
 }
}
